28	/**
29	 * A structured result of fully resolved sandbox paths.
30	 * All paths in this object are absolute, deduplicated, and expanded to include
31	 * both the original path and its real target (if it is a symlink).
32	 */
33	export interface ResolvedSandboxPaths {
34	  /** The primary workspace directory. */
35	  workspace: {
36	    /** The original path provided in the sandbox options. */
37	    original: string;
38	    /** The real path. */
39	    resolved: string;
40	  };
41	  /** Explicitly denied paths. */
42	  forbidden: string[];
43	  /** Directories included globally across all commands in this sandbox session. */
44	  globalIncludes: string[];
45	  /** Paths explicitly allowed by the policy of the currently executing command. */
46	  policyAllowed: string[];
47	  /** Paths granted temporary read access by the current command's dynamic permissions. */
48	  policyRead: string[];
49	  /** Paths granted temporary write access by the current command's dynamic permissions. */
50	  policyWrite: string[];
51	  /** Auto-detected paths for git worktrees/submodules. */
52	  gitWorktree?: {
53	    /** The actual .git directory for this worktree. */
54	    worktreeGitDir: string;
55	    /** The main repository's .git directory (if applicable). */
56	    mainGitDir?: string;
57	  };
58	}
59	
60	export interface SandboxPermissions {
61	  /** Filesystem permissions. */
62	  fileSystem?: {
63	    /** Paths that should be readable by the command. */
64	    read?: string[];
65	    /** Paths that should be writable by the command. */
66	    write?: string[];
67	  };
68	  /** Whether the command should have network access. */
69	  network?: boolean;
70	}
71	
72	/**
73	 * Security boundaries and permissions applied to a specific sandboxed execution.
74	 */
75	export interface ExecutionPolicy {
76	  /** Additional absolute paths to grant full read/write access to. */
77	  allowedPaths?: string[];
78	  /** Whether network access is allowed. */
79	  networkAccess?: boolean;
80	  /** Rules for scrubbing sensitive environment variables. */
81	  sanitizationConfig?: Partial<EnvironmentSanitizationConfig>;
82	  /** Additional granular permissions to grant to this command. */
83	  additionalPermissions?: SandboxPermissions;
84	}
85	
86	/**
87	 * Configuration for the sandbox mode behavior.
88	 */
89	export interface SandboxModeConfig {
90	  readonly?: boolean;
91	  network?: boolean;
92	  approvedTools?: string[];
93	  allowOverrides?: boolean;
94	  yolo?: boolean;
95	}
96	
97	/**
98	 * Global configuration options used to initialize a SandboxManager.
99	 */
100	export interface GlobalSandboxOptions {
101	  /** The absolute path to the primary workspace directory, granted full read/write access. */
102	  workspace: string;
103	  /** Absolute paths to explicitly include in the workspace context. */
104	  includeDirectories?: string[];
105	  /** An optional asynchronous resolver function for paths that should be explicitly denied. */
106	  forbiddenPaths?: () => Promise<string[]>;
107	  /** The current sandbox mode behavior from config. */
108	  modeConfig?: SandboxModeConfig;
109	  /** The policy manager for persistent approvals. */
110	  policyManager?: SandboxPolicyManager;
111	}
112	
113	/**
114	 * Request for preparing a command to run in a sandbox.
115	 */
116	export interface SandboxRequest {
117	  /** The program to execute. */
118	  command: string;
119	  /** Arguments for the program. */
120	  args: string[];
121	  /** The working directory. */
122	  cwd: string;
123	  /** Environment variables to be passed to the program. */
124	  env: NodeJS.ProcessEnv;
125	  /** Policy to use for this request. */
126	  policy?: ExecutionPolicy;
127	}
128	
129	/**
130	 * A command that has been prepared for sandboxed execution.
131	 */
132	export interface SandboxedCommand {
133	  /** The program or wrapper to execute. */
134	  program: string;
135	  /** Final arguments for the program. */
136	  args: string[];
137	  /** Sanitized environment variables. */
138	  env: NodeJS.ProcessEnv;
139	  /** The working directory. */
140	  cwd?: string;
141	  /** An optional cleanup function to be called after the command terminates. */
142	  cleanup?: () => void;
143	}
