145	/**
146	 * A structured result from parsing sandbox denials.
147	 */
148	export interface ParsedSandboxDenial {
149	  /** If the denial is related to file system access, these are the paths that were blocked. */
150	  filePaths?: string[];
151	  /** If the denial is related to network access. */
152	  network?: boolean;
153	}
