155	/**
156	 * Interface for a service that prepares commands for sandboxed execution.
157	 */
158	export interface SandboxManager {
159	  /**
160	   * Prepares a command to run in a sandbox, including environment sanitization.
161	   */
162	  prepareCommand(req: SandboxRequest): Promise<SandboxedCommand>;
163	
164	  /**
165	   * Checks if a command with its arguments is known to be safe for this sandbox.
166	   */
167	  isKnownSafeCommand(args: string[]): boolean;
168	
169	  /**
170	   * Checks if a command with its arguments is explicitly known to be dangerous for this sandbox.
171	   */
172	  isDangerousCommand(args: string[]): boolean;
173	
174	  /**
175	   * Parses the output of a command to detect sandbox denials.
176	   */
177	  parseDenials(result: ShellExecutionResult): ParsedSandboxDenial | undefined;
178	
179	  /**
180	   * Returns the primary workspace directory for this sandbox.
181	   */
182	  getWorkspace(): string;
183	
184	  /**
185	   * Returns the global sandbox options for this sandbox.
186	   */
187	  getOptions(): GlobalSandboxOptions | undefined;
188	}
