190	/**
191	 * Files that represent the governance or "constitution" of the repository
192	 * and should be write-protected in any sandbox.
193	 */
194	export const GOVERNANCE_FILES = [
195	  { path: '.gitignore', isDirectory: false },
196	  { path: '.geminiignore', isDirectory: false },
197	  { path: '.git', isDirectory: true },
198	] as const;
199	
200	/**
201	 * Files that contain sensitive secrets or credentials and should be
202	 * completely hidden (deny read/write) in any sandbox.
203	 */
204	export const SECRET_FILES = [
205	  { pattern: '.env' },
206	  { pattern: '.env.*' },
207	] as const;
208	
209	/**
210	 * Checks if a given file name matches any of the secret file patterns.
