29	/**
30	 * Builds the list of bubblewrap arguments based on the provided options.
31	 */
32	export async function buildBwrapArgs(
33	  options: BwrapArgsOptions,
34	): Promise<string[]> {
35	  const {
36	    resolvedPaths,
37	    workspaceWrite,
38	    networkAccess,
39	    maskFilePath,
40	    isWriteCommand,
41	  } = options;
42	  const { workspace } = resolvedPaths;
43	
44	  const bwrapArgs: string[] = [
45	    '--unshare-all',
46	    '--new-session', // Isolate session
47	    '--die-with-parent', // Prevent orphaned runaway processes
48	  ];
49	
50	  if (networkAccess) {
51	    bwrapArgs.push('--share-net');
52	  }
53	
54	  bwrapArgs.push(
55	    '--ro-bind',
56	    '/',
57	    '/',
58	    '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
59	    '/dev',
60	    '--proc', // Creates a fresh procfs for the unshared PID namespace
61	    '/proc',
62	    '--tmpfs', // Provides an isolated, writable /tmp directory
63	    '/tmp',
64	  );
65	
66	  const bindFlag = workspaceWrite ? '--bind-try' : '--ro-bind-try';
67	
68	  bwrapArgs.push(bindFlag, workspace.original, workspace.original);
69	  if (workspace.resolved !== workspace.original) {
70	    bwrapArgs.push(bindFlag, workspace.resolved, workspace.resolved);
71	  }
72	
73	  for (const includeDir of resolvedPaths.globalIncludes) {
74	    bwrapArgs.push('--ro-bind-try', includeDir, includeDir);
75	  }
76	
77	  for (const allowedPath of resolvedPaths.policyAllowed) {
78	    if (fs.existsSync(allowedPath)) {
79	      bwrapArgs.push('--bind-try', allowedPath, allowedPath);
80	    } else {
81	      // If the path doesn't exist, we still want to allow access to its parent
82	      // to enable creating it. Since allowedPath is already resolved by resolveSandboxPaths,
83	      // its parent is also correctly resolved.
84	      const parent = dirname(allowedPath);
85	      bwrapArgs.push(isWriteCommand ? '--bind-try' : bindFlag, parent, parent);
86	    }
87	  }
88	
89	  for (const p of resolvedPaths.policyRead) {
90	    bwrapArgs.push('--ro-bind-try', p, p);
91	  }
92	
93	  for (const p of resolvedPaths.policyWrite) {
94	    bwrapArgs.push('--bind-try', p, p);
95	  }
96	
97	  for (const file of GOVERNANCE_FILES) {
98	    const filePath = join(workspace.original, file.path);
99	    const realPath = join(workspace.resolved, file.path);
100	    bwrapArgs.push('--ro-bind', filePath, filePath);
101	    if (realPath !== filePath) {
102	      bwrapArgs.push('--ro-bind', realPath, realPath);
103	    }
104	  }
105	
106	  // Grant read-only access to git worktrees/submodules. We do this last in order to
107	  // ensure that these rules aren't overwritten by broader write policies.
108	  if (resolvedPaths.gitWorktree) {
109	    const { worktreeGitDir, mainGitDir } = resolvedPaths.gitWorktree;
110	    if (worktreeGitDir) {
111	      bwrapArgs.push('--ro-bind-try', worktreeGitDir, worktreeGitDir);
112	    }
113	    if (mainGitDir) {
114	      bwrapArgs.push('--ro-bind-try', mainGitDir, mainGitDir);
115	    }
116	  }
117	
118	  for (const p of resolvedPaths.forbidden) {
119	    if (!fs.existsSync(p)) continue;
120	    try {
121	      const stat = fs.statSync(p);
122	      if (stat.isDirectory()) {
123	        bwrapArgs.push('--tmpfs', p, '--remount-ro', p);
124	      } else {
125	        bwrapArgs.push('--ro-bind', '/dev/null', p);
126	      }
127	    } catch (e: unknown) {
128	      if (isErrnoException(e) && e.code === 'ENOENT') {
129	        bwrapArgs.push('--symlink', '/dev/null', p);
130	      } else {
131	        debugLogger.warn(
132	          `Failed to secure forbidden path ${p}: ${e instanceof Error ? e.message : String(e)}`,
133	        );
134	        bwrapArgs.push('--ro-bind', '/dev/null', p);
135	      }
136	    }
137	  }
138	
139	  // Mask secret files (.env, .env.*)
140	  const secretArgs = await getSecretFilesArgs(resolvedPaths, maskFilePath);
141	  bwrapArgs.push(...secretArgs);
142	
143	  return bwrapArgs;
144	}
