146	/**
147	 * Generates bubblewrap arguments to mask secret files.
148	 */
149	async function getSecretFilesArgs(
150	  resolvedPaths: ResolvedSandboxPaths,
151	  maskPath: string,
152	): Promise<string[]> {
153	  const args: string[] = [];
154	  const searchDirs = new Set([
155	    resolvedPaths.workspace.original,
156	    resolvedPaths.workspace.resolved,
157	    ...resolvedPaths.policyAllowed,
158	    ...resolvedPaths.globalIncludes,
159	  ]);
160	  const findPatterns = getSecretFileFindArgs();
161	
162	  for (const dir of searchDirs) {
163	    try {
164	      // Use the native 'find' command for performance and to catch nested secrets.
165	      // We limit depth to 3 to keep it fast while covering common nested structures.
166	      // We use -prune to skip heavy directories efficiently while matching dotfiles.
167	      const findResult = await spawnAsync('find', [
168	        dir,
169	        '-maxdepth',
170	        '3',
171	        '-type',
172	        'd',
173	        '(',
174	        '-name',
175	        '.git',
176	        '-o',
177	        '-name',
178	        'node_modules',
179	        '-o',
180	        '-name',
181	        '.venv',
182	        '-o',
183	        '-name',
184	        '__pycache__',
185	        '-o',
186	        '-name',
187	        'dist',
188	        '-o',
189	        '-name',
190	        'build',
191	        ')',
192	        '-prune',
193	        '-o',
194	        '-type',
195	        'f',
196	        ...findPatterns,
197	        '-print0',
198	      ]);
199	
200	      const files = findResult.stdout.toString().split('\0');
201	      for (const file of files) {
202	        if (file.trim()) {
203	          args.push('--bind', maskPath, file.trim());
204	        }
205	      }
206	    } catch (e) {
207	      debugLogger.log(
208	        `LinuxSandboxManager: Failed to find or mask secret files in ${dir}`,
209	        e,
210	      );
211	    }
212	  }
213	  return args;
214	}
