      // 2. Set the Mandatory Label to Low to allow "Write Up" from Low processes
      await spawnAsync('icacls', [
        resolvedPath,
        '/grant',
        `${LOW_INTEGRITY_SID}:${flags}(M)`,
        '/setintegritylevel',
        `${flags}Low`,
      ]);
